"""Business output projection and read-only notebook inspection of the final sink."""
from pathlib import Path
from .knowledge_stages import material_id


class BuildKnowledgeRecord:
    """One concept material batch -> layered concept/documents/images/knowledge/audit."""
    def __call__(self,row):
        documents=[];images=[];identities=[]
        selected={material_id(dict(m)):m['image_id'] for m in row.get('material_pack',{}).get('images',[])}
        for material in row['cleaned_materials']:
            m=dict(material);kind=m['kind']
            if kind in {'legacy_concepts','qid_concepts','qid_concepts_base'}:
                identities.append({'record':m['record'],'source':m['provenance']});continue
            m['material_id']=material_id(m)
            if kind in {'legacy_images','qid_images'}:
                m['image_id']=selected.get(m['material_id']);images.append(m)
            else:documents.append(m)
        return {'schema':'concept-knowledge-record/1','case_id':row['case_id'],
            'concept':{'concept_ref':row['concept_ref'],'concept_id':row['bundle']['concept_id'],
                       'request':row['bundle']['request'],'source_records':identities,'identity':row.get('identity')},
            'documents':documents,'images':images,'knowledge':row['export'],
            'audit':{'input_scope':row.get('input_scope'),'blocked':row.get('blocked'),
                     'identity_unexamined':row.get('identity_unexamined'),
                     'material_selection':row.get('material_pack'),
                     'extraction_call':row.get('extraction_call'),
                     'consolidation_call':row.get('consolidation_call')}}


def view_knowledge(path, *, limit=10, concept_ids=None, sample_rate=1., seed=42,
                   show_documents=False, show_images=True, max_images=4,
                   image_scope='reviewed', show_deferred=True):
    """Inspect saved final records only. Display limits never alter processing."""
    from demiflow.standalone import local_data
    from IPython.display import display, Markdown, Image
    from .notebook_debug import show,detail
    if not isinstance(limit,int) or limit<1:raise ValueError('limit must be positive')
    if max_images is not None and max_images<0:raise ValueError('max_images must be nonnegative or None')
    if image_scope not in {'reviewed','all'}:raise ValueError('image_scope must be reviewed/all')
    if not 0<=sample_rate<=1:raise ValueError('sample_rate must be in [0,1]')
    path=Path(path)
    if not path.exists():
        display(Markdown(f'尚无最终文件：`{path}`。运行至 export 后生成；本查看函数不会执行 pipeline。'));return
    data=local_data().read_json(str(path))
    if concept_ids is not None:
        allowed=set(concept_ids);data=data.filter(lambda r:r['concept']['concept_ref'] in allowed)
    if sample_rate<1:data=data.random_sample(sample_rate,seed=seed)
    rows=data.take(limit)
    display(Markdown(f'最终文件：`{path}` · 本次显示 {len(rows)} 个材料批次（最多 {limit} 个）。图片支持和知识审核状态分别展示。'))
    for row in rows:
        concept=row['concept'];knowledge=row['knowledge'];evidence=knowledge.get('image_evidence') or {}
        result=evidence.get('result',{});support=result.get('support',[])
        captions={im['image_id']:im.get('caption','') for im in result.get('images',[])}
        display(Markdown(f"### {concept['concept_ref']}\n\n状态：`{knowledge['status']}`；原始文档 {len(row['documents'])} 篇、图片 {len(row['images'])} 张。"))
        if knowledge.get('blocked'):detail({'blocked':knowledge['blocked']})
        display(Markdown('**知识候选**：含陈述、条件、例外及来源引文；不代表已人工核验。'))
        show(knowledge.get('facts',[]),limit=100)
        if show_deferred:
            display(Markdown('**暂缓知识与未解争议**'))
            detail({'deferred_facts':knowledge.get('deferred_facts',[]),'unresolved_conflicts':knowledge.get('unresolved_conflicts',[])})
        if show_documents:
            display(Markdown('**原始资料与清洗记录**：展开字段查看原文、来源定位、清洗块。'))
            show(row['documents'],limit=len(row['documents']) or 1)
        if show_images:
            candidates=[m for m in row['images'] if image_scope=='all' or m.get('image_id') in captions]
            selected=candidates if max_images is None else candidates[:max_images]
            display(Markdown(f'**图片**：显示 {len(selected)}/{len(candidates)} 张（范围：{image_scope}）。`none`表示不能支持对应知识，不表示没有相关材料。'))
            for m in selected:
                image_id=m.get('image_id');byte_info=m.get('bytes') or {};image_path=byte_info.get('path')
                detail({'image_id':image_id,'material_id':m['material_id'],
                        'source_caption':m['record'].get('caption'),
                        'model_caption_unverified':captions.get(image_id),
                        'support':[s for s in support if s['image_id']==image_id],
                        'byte_status':byte_info.get('status'),'path':image_path})
                if image_path and byte_info.get('status')=='verified_bytes' and Path(image_path).is_file():
                    # Display existing bytes, without remote downloads or image generation.
                    display(Image(filename=str(image_path),width=360))
                else:display(Markdown('本地图片不可展示；缺口与记录保留在最终文件。'))
        display(Markdown('未查看范围、补证任务与完整原始资料均保留在文件的 concept/documents/images/knowledge/audit 各层。'))
